"""Apply the Apify findings of 2026-11-11 (work/apify/APIFY_RESULTS_2026-11-11.md) to the site sources. Run once from work/site."""
import pathlib, json
H = pathlib.Path(__file__).parent
def rep(path, pairs):
    p = H / path; t = p.read_text(encoding="utf-8")
    for a, b in pairs:
        n = t.count(a); assert n == 1, (path, a[:60], n); t = t.replace(a, b)
    p.write_text(t, encoding="utf-8"); print("ok", path, len(pairs))

